INSERT IGNORE INTO ipd_capability_pack_item
(id,tenant_id,pack_id,item_type,item_ref,item_version,sha256,`required`,sort_order,del_flag,create_by,create_time)
SELECT 930000000000000013,p.tenant_id,p.id,'SKILL','market-opportunity-research-ipd','1.1.0',
'c116dac4094ed5dea7013a7952943f5482e1632880c40287b4f0130641223c28',1,0,'0',-1,NOW()
FROM ipd_capability_pack p
WHERE p.id=930000000000000001 AND p.tenant_id='000000' AND p.source='BUILTIN'
AND p.code='market-research' AND p.version='v1' AND p.del_flag='0'
AND (p.action_codes=JSON_ARRAY('C02') OR p.action_codes=JSON_ARRAY('C01','C02'));
UPDATE ipd_capability_pack SET action_codes=JSON_ARRAY('C01','C02')
WHERE id=930000000000000001 AND tenant_id='000000' AND source='BUILTIN'
AND code='market-research' AND version='v1' AND del_flag='0' AND action_codes=JSON_ARRAY('C02');
COMMIT;
